CREATE TABLE activities (activity_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts(account_id) ON DELETE RESTRICT, country_code char(2) NOT NULL REFERENCES countries(code), owner_user_id uuid NOT NULL REFERENCES app_users(id), type_code text NOT NULL, subject text, notes text, due_at timestamptz, task_status_code text, completed_at timestamptz, cancelled_at timestamptz, cancel_reason text, row_version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT activities_cancel_shape CHECK ((task_status_code <> 'CANCELLED') OR (cancelled_at IS NOT NULL AND cancel_reason IS NOT NULL)));
CREATE TABLE activity_history (activity_history_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), activity_id uuid NOT NULL REFERENCES activities(activity_id) ON DELETE RESTRICT, event_code text NOT NULL, reason text, actor_user_id uuid NOT NULL REFERENCES app_users(id), occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE activity_reminders (activity_reminder_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), activity_id uuid NOT NULL REFERENCES activities(activity_id) ON DELETE RESTRICT, due_at timestamptz NOT NULL, status_code text NOT NULL DEFAULT 'ACTIVE', cancelled_at timestamptz);
CREATE INDEX activities_scope_due_idx ON activities(country_code, owner_user_id, due_at, activity_id);
CREATE INDEX activity_history_activity_id_occurred_at_activity_history_id_idx ON activity_history(activity_id, occurred_at, activity_history_id);
CREATE INDEX activity_reminders_activity_id_status_code_idx ON activity_reminders(activity_id, status_code);
